import{_ as e,o as l,c as a,a2 as r}from"./chunks/framework.CNQbXYGB.js";const u=JSON.parse('{"title":"案例 2：大模型关键算子迁移与 Kernel 优化分析清单","description":"","frontmatter":{},"headers":[],"relativePath":"cases/llm-operators-playbook.md","filePath":"cases/llm-operators-playbook.md"}'),i={name:"cases/llm-operators-playbook.md"};function d(o,t,n,h,p,c){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="案例-2-大模型关键算子迁移与-kernel-优化分析清单" tabindex="-1">案例 2：大模型关键算子迁移与 Kernel 优化分析清单 <a class="header-anchor" href="#案例-2-大模型关键算子迁移与-kernel-优化分析清单" aria-label="Permalink to &quot;案例 2：大模型关键算子迁移与 Kernel 优化分析清单&quot;">​</a></h1><h2 id="八、把这些知识迁移到大模型关键算子" tabindex="-1">八、把这些知识迁移到大模型关键算子 <a class="header-anchor" href="#八、把这些知识迁移到大模型关键算子" aria-label="Permalink to &quot;八、把这些知识迁移到大模型关键算子&quot;">​</a></h2><p>掌握以上内容后，可以用同样的方法研究 GEMM、Attention、MoE 等算子。</p><table tabindex="0"><thead><tr><th>算子</th><th>重点硬件资源</th><th>典型性能问题</th></tr></thead><tbody><tr><td>GEMM</td><td>MMAC、VGPR、LDS、HBM</td><td>矩阵指令利用率不足、Tile 不合理、资源压力过高</td></tr><tr><td>FlashAttention</td><td>MMAC、LDS、VGPR、特殊函数</td><td>QKV 数据搬运、Softmax、计算访存重叠</td></tr><tr><td>PagedAttention</td><td>VMEM、Cache、HBM、Scheduler</td><td>KV 访问不规则、访存带宽或并行度不足</td></tr><tr><td>MoE Grouped GEMM</td><td>MMAC、Scheduler、VGPR</td><td>小矩阵利用率不足、专家负载不均衡</td></tr><tr><td>RMSNorm</td><td>VALU、LDS、VMEM</td><td>Reduction、访存和同步开销</td></tr><tr><td>LSTM Persistent Kernel</td><td>MMAC、LDS、VGPR、Scheduler</td><td>Recurrent 计算、状态复用、资源驻留限制</td></tr></tbody></table><p>这些算子虽然计算公式不同，但底层优化思路有共通之处：</p><p><strong>先分析执行资源和数据路径，再判断性能瓶颈，最后调整 Kernel 组织方式。</strong></p><hr><h2 id="九、实际优化时应该怎样分析一个-kernel" tabindex="-1">九、实际优化时应该怎样分析一个 Kernel？ <a class="header-anchor" href="#九、实际优化时应该怎样分析一个-kernel" aria-label="Permalink to &quot;九、实际优化时应该怎样分析一个 Kernel？&quot;">​</a></h2><p>建议将后续所有 Kernel 优化统一成以下分析流程。</p><h3 id="_9-1-明确计算任务" tabindex="-1">9.1 明确计算任务 <a class="header-anchor" href="#_9-1-明确计算任务" aria-label="Permalink to &quot;9.1 明确计算任务&quot;">​</a></h3><p>需要掌握：</p><ul><li>Kernel 输入输出 Shape。</li><li>数据类型。</li><li>计算量。</li><li>读写数据量。</li><li>Batch、Sequence Length 等业务参数。</li></ul><h3 id="_9-2-明确线程映射" tabindex="-1">9.2 明确线程映射 <a class="header-anchor" href="#_9-2-明确线程映射" aria-label="Permalink to &quot;9.2 明确线程映射&quot;">​</a></h3><p>需要掌握：</p><ul><li>Grid Size。</li><li>Block Size。</li><li>每 Block Wavefront 数量。</li><li>每 Wavefront 负责哪些数据。</li><li>每个 Lane 负责哪些矩阵片段。</li></ul><h3 id="_9-3-明确资源使用" tabindex="-1">9.3 明确资源使用 <a class="header-anchor" href="#_9-3-明确资源使用" aria-label="Permalink to &quot;9.3 明确资源使用&quot;">​</a></h3><p>需要掌握：</p><ul><li>VGPR、SGPR 用量。</li><li>LDS 用量。</li><li>Occupancy。</li><li>是否存在寄存器 Spill。</li><li>Workgroup 驻留数量。</li></ul><h3 id="_9-4-明确指令执行" tabindex="-1">9.4 明确指令执行 <a class="header-anchor" href="#_9-4-明确指令执行" aria-label="Permalink to &quot;9.4 明确指令执行&quot;">​</a></h3><p>需要掌握：</p><ul><li>生成了哪些矩阵指令。</li><li>MMAC、VALU、LDS、VMEM 等指令的使用情况。</li><li>是否存在长指令依赖链。</li><li>计算与数据搬运是否有效重叠。</li></ul><h3 id="_9-5-明确性能瓶颈" tabindex="-1">9.5 明确性能瓶颈 <a class="header-anchor" href="#_9-5-明确性能瓶颈" aria-label="Permalink to &quot;9.5 明确性能瓶颈&quot;">​</a></h3><p>根据实际 Profiling 与 Microbenchmark，判断主要问题属于：</p><ul><li>计算吞吐不足。</li><li>访存带宽不足。</li><li>内存延迟。</li><li>并行度不足。</li><li>资源限制。</li><li>指令依赖或调度停顿。</li><li>Kernel 启动与同步开销。</li></ul><h3 id="_9-6-优化与验证" tabindex="-1">9.6 优化与验证 <a class="header-anchor" href="#_9-6-优化与验证" aria-label="Permalink to &quot;9.6 优化与验证&quot;">​</a></h3><p>每次只调整少量变量，形成可对比实验。</p><p>例如：</p><ul><li>Block Size：64 / 128 / 256 / 512。</li><li>不同矩阵 Tile。</li><li>不同 LDS Layout。</li><li>不同寄存器 Blocking。</li><li>Persistent 与非 Persistent。</li><li>不同 Wavefront 任务映射。</li></ul><p>最终不仅记录性能提升，还需要解释性能变化的原因。</p><hr><h2 id="十、需要从海光-dcu-研发侧进一步确认的问题" tabindex="-1">十、需要从海光 DCU 研发侧进一步确认的问题 <a class="header-anchor" href="#十、需要从海光-dcu-研发侧进一步确认的问题" aria-label="Permalink to &quot;十、需要从海光 DCU 研发侧进一步确认的问题&quot;">​</a></h2><p>结合现有 z100 架构资料以及后续下一代 DCU 研究需求，建议重点确认：</p><table tabindex="0"><thead><tr><th>研究方向</th><th>需要确认的具体信息</th></tr></thead><tbody><tr><td>CU / SIMD</td><td>CU 组织、SIMD 数量、物理 Lane 宽度及 Wavefront Size</td></tr><tr><td>Scheduler</td><td>Wavefront 驻留上限、调度和指令发射机制</td></tr><tr><td>MMAC</td><td>指令形状、数据类型、Lane Layout、延迟和吞吐</td></tr><tr><td>VGPR / SGPR</td><td>容量、分配粒度、资源占用限制及 Spill 行为</td></tr><tr><td>LDS</td><td>容量、Bank 组织、访问粒度、吞吐及冲突规则</td></tr><tr><td>Cache / HBM</td><td>缓存层级、带宽、访问延迟和数据路径</td></tr><tr><td>编译器</td><td>HIP/Triton 到 ISA 的映射、寄存器分配及优化选项</td></tr><tr><td>Profiling</td><td>硬件计数器、指令执行、Stall、访存与矩阵计算指标</td></tr></tbody></table><p>应优先获取与实际运行芯片型号匹配的参数和工具说明。</p><p>对于下一代 DCU，需要特别关注哪些微架构变化会影响当前已经积累的 Kernel 优化策略。</p><hr><h2 id="十一、最终总结-怎样理解整个-dcu-微架构" tabindex="-1">十一、最终总结：怎样理解整个 DCU 微架构？ <a class="header-anchor" href="#十一、最终总结-怎样理解整个-dcu-微架构" aria-label="Permalink to &quot;十一、最终总结：怎样理解整个 DCU 微架构？&quot;">​</a></h2><p>可以把 DCU 看成一个具备大量并行计算资源的系统。</p><p><strong>任务组织方面：</strong></p><p>Grid 负责组织全部计算任务，Block 负责组织线程协作，Wavefront 是重要的硬件执行单位，CU 则提供实际计算资源。</p><p><strong>指令执行方面：</strong></p><p>Scheduler 选择就绪 Wavefront，SALU 处理标量与控制操作，VALU 处理向量计算，MMAC 完成高吞吐矩阵乘加，访存单元负责数据加载和存储。</p><p><strong>数据存储方面：</strong></p><p>VGPR/SGPR 保存指令执行所需的寄存器值，LDS 支持 Block 内的数据共享和复用，Cache 减少部分全局访存成本，HBM 保存大容量模型数据。</p><p><strong>性能优化方面：</strong></p><p>Occupancy 影响可驻留并参与延迟隐藏的 Wavefront 数量；寄存器和 LDS 决定部分资源使用上限；指令流水和数据依赖影响计算效率；访存模式和数据复用影响数据供给效率。</p><p>对于实际算子优化，不能只关注某一种硬件资源。</p><p>真正高效的 Kernel，需要在计算、访存、寄存器、LDS、指令调度与并行度之间取得平衡。</p><p>因此可以把整个专题的核心理解为：</p><p><strong>GPU Kernel 优化，本质上是让计算任务以适合目标微架构的方式组织执行，并让硬件计算能力、数据供给能力和调度能力尽可能协调工作。</strong></p>',50)])])}const S=e(i,[["render",d]]);export{u as __pageData,S as default};
